-- Phase 1E4: durable Test transfer receipt, one authoritative settlement path,
-- and operational reconciliation.  No transfer is initiated by this migration.
begin;

create table if not exists public.learning_instructor_payout_provider_events (
  id bigint generated by default as identity primary key,
  provider text not null default 'paystack' check (provider='paystack'),
  provider_domain text not null default 'test' check (provider_domain='test'),
  provenance text not null check (provenance in ('provider_webhook','provider_api')),
  provider_event_id text not null unique,
  payload_digest text check (payload_digest is null or payload_digest ~ '^[a-f0-9]{64}$'),
  payout_item_reference text not null check (payout_item_reference ~ '^lpi-[a-z0-9_-]{12,50}$'),
  provider_transfer_id text not null check (provider_transfer_id ~ '^[0-9]+$'),
  provider_transfer_code text check (provider_transfer_code is null or provider_transfer_code ~ '^TRF_[A-Za-z0-9]+$'),
  provider_status text not null check (provider_status in ('succeeded','failed','reversed','pending')),
  amount_minor bigint not null check (amount_minor>0),
  currency text not null check (currency='NGN'),
  received_at timestamptz not null default now()
);
create index if not exists learning_instructor_payout_provider_events_reference_idx on public.learning_instructor_payout_provider_events(payout_item_reference,received_at,id);

create table if not exists public.learning_instructor_payout_event_processing_attempts (
  id bigint generated by default as identity primary key,
  provider_event_id bigint not null references public.learning_instructor_payout_provider_events(id) on delete restrict,
  payout_item_id bigint references public.learning_instructor_payout_items(id) on delete restrict,
  outcome text not null check (outcome in ('settled','released','reversed','recorded','deferred','conflict','already_processed')),
  detail text not null check (length(detail)<=500),
  processed_at timestamptz not null default now()
);
-- A retained/deferred receipt is not a completed financial outcome.  It must
-- therefore not consume the exactly-once slot needed when a later controlled
-- reprocess can safely release a protected failed reservation.
create unique index if not exists learning_instructor_payout_event_processing_terminal_key on public.learning_instructor_payout_event_processing_attempts(provider_event_id) where outcome in ('settled','released','reversed','already_processed');

create table if not exists public.learning_instructor_payout_settlements (
  id bigint generated by default as identity primary key,
  payout_item_id bigint not null unique references public.learning_instructor_payout_items(id) on delete restrict,
  earning_id bigint not null unique references public.learning_instructor_earnings(id) on delete restrict,
  reservation_id bigint not null unique references public.learning_instructor_earning_reservations(id) on delete restrict,
  ledger_transaction_id bigint not null unique references public.learning_ledger_transactions(id) on delete restrict,
  provider_event_id bigint not null references public.learning_instructor_payout_provider_events(id) on delete restrict,
  amount_minor bigint not null check (amount_minor>0),
  currency text not null check (currency='NGN'),
  settled_at timestamptz not null default now()
);

create table if not exists public.learning_instructor_payout_reconciliation_findings (
  id bigint generated by default as identity primary key,
  finding_key text not null unique check (finding_key ~ '^[a-z][a-z0-9:_-]{3,180}$'),
  payout_item_id bigint references public.learning_instructor_payout_items(id) on delete restrict,
  provider_event_id bigint references public.learning_instructor_payout_provider_events(id) on delete restrict,
  finding_type text not null check (finding_type in ('unmatched_provider_event','provider_identity_mismatch','provider_amount_currency_mismatch','pending_payout','recovery_required_payout','terminal_payout_missing_settlement','terminal_payout_inconsistent_state','settled_payout_reversed_requires_controlled_resolution','provider_outcome_financially_blocked','provider_outcome_conflict')),
  status text not null default 'open' check (status in ('open','resolved')),
  detail text not null check (length(detail)<=500),
  created_at timestamptz not null default now(),
  resolved_at timestamptz
);
create index if not exists learning_instructor_payout_reconciliation_findings_open_idx on public.learning_instructor_payout_reconciliation_findings(status,created_at desc,id desc);

alter table public.learning_instructor_payout_provider_events enable row level security;
alter table public.learning_instructor_payout_event_processing_attempts enable row level security;
alter table public.learning_instructor_payout_settlements enable row level security;
alter table public.learning_instructor_payout_reconciliation_findings enable row level security;
revoke all on public.learning_instructor_payout_provider_events,public.learning_instructor_payout_event_processing_attempts,public.learning_instructor_payout_settlements,public.learning_instructor_payout_reconciliation_findings from public,anon,authenticated;
grant select,insert,update,delete on public.learning_instructor_payout_provider_events,public.learning_instructor_payout_event_processing_attempts,public.learning_instructor_payout_settlements,public.learning_instructor_payout_reconciliation_findings to postgres,service_role;

create or replace function public.prevent_learning_instructor_payout_e4_history_mutation()
returns trigger language plpgsql security definer set search_path to '' as $function$
begin raise exception 'Payout provider and settlement history is append-only' using errcode='42501'; end;$function$;
do $trigger$
begin
  if not exists(select 1 from pg_trigger where tgrelid='public.learning_instructor_payout_provider_events'::regclass and tgname='prevent_learning_instructor_payout_provider_event_mutation' and not tgisinternal) then
    execute 'create trigger prevent_learning_instructor_payout_provider_event_mutation before update or delete on public.learning_instructor_payout_provider_events for each row execute function public.prevent_learning_instructor_payout_e4_history_mutation()';
  end if;
  if not exists(select 1 from pg_trigger where tgrelid='public.learning_instructor_payout_event_processing_attempts'::regclass and tgname='prevent_learning_instructor_payout_event_processing_mutation' and not tgisinternal) then
    execute 'create trigger prevent_learning_instructor_payout_event_processing_mutation before update or delete on public.learning_instructor_payout_event_processing_attempts for each row execute function public.prevent_learning_instructor_payout_e4_history_mutation()';
  end if;
  if not exists(select 1 from pg_trigger where tgrelid='public.learning_instructor_payout_settlements'::regclass and tgname='prevent_learning_instructor_payout_settlement_mutation' and not tgisinternal) then
    execute 'create trigger prevent_learning_instructor_payout_settlement_mutation before update or delete on public.learning_instructor_payout_settlements for each row execute function public.prevent_learning_instructor_payout_e4_history_mutation()';
  end if;
end $trigger$;

create or replace function public.prevent_learning_instructor_payout_finding_mutation()
returns trigger language plpgsql security definer set search_path to '' as $function$
begin
  if tg_op='DELETE' then raise exception 'Payout reconciliation history is retained' using errcode='42501'; end if;
  if old.finding_key is distinct from new.finding_key or old.payout_item_id is distinct from new.payout_item_id or old.provider_event_id is distinct from new.provider_event_id or old.finding_type is distinct from new.finding_type or old.detail is distinct from new.detail or old.created_at is distinct from new.created_at then raise exception 'Payout reconciliation identity is immutable' using errcode='42501'; end if;
  if old.status='open' and new.status='resolved' and new.resolved_at is not null then return new; end if;
  raise exception 'Unsupported payout reconciliation transition' using errcode='22023';
end;$function$;
do $trigger$
begin
  if not exists(select 1 from pg_trigger where tgrelid='public.learning_instructor_payout_reconciliation_findings'::regclass and tgname='prevent_learning_instructor_payout_finding_mutation' and not tgisinternal) then
    execute 'create trigger prevent_learning_instructor_payout_finding_mutation before update or delete on public.learning_instructor_payout_reconciliation_findings for each row execute function public.prevent_learning_instructor_payout_finding_mutation()';
  end if;
end $trigger$;

alter table public.learning_ledger_transactions drop constraint if exists learning_ledger_transactions_transaction_type_check;
alter table public.learning_ledger_transactions add constraint learning_ledger_transactions_transaction_type_check check (transaction_type in ('payment_capture','processor_fee','refund','chargeback','adjustment','commercial_allocation','instructor_earnings_release','instructor_earnings_reversal','instructor_payout_settlement'));

create or replace function public.open_learning_instructor_payout_finding(p_finding_key text,p_payout_item_id bigint,p_provider_event_id bigint,p_finding_type text,p_detail text)
returns void language plpgsql security definer set search_path to '' as $function$
begin
  insert into public.learning_instructor_payout_reconciliation_findings(finding_key,payout_item_id,provider_event_id,finding_type,detail)
  values(p_finding_key,p_payout_item_id,p_provider_event_id,p_finding_type,left(p_detail,500))
  on conflict (finding_key) do nothing;
end;$function$;

create or replace function public.receive_paystack_test_transfer_provider_event(p_provenance text,p_provider_event_id text,p_payload_digest text,p_reference text,p_transfer_id text,p_transfer_code text,p_status text,p_amount_minor bigint,p_currency text,p_actor_user_id uuid default null)
returns table(outcome text,provider_event_id bigint) language plpgsql security definer set search_path to '' as $function$
declare event_id bigint; existing public.learning_instructor_payout_provider_events%rowtype; item_id bigint;
begin
  if p_provenance not in ('provider_webhook','provider_api') or p_provider_event_id is null or p_payload_digest !~ '^[a-f0-9]{64}$' or p_reference !~ '^lpi-[a-z0-9_-]{12,50}$' or p_transfer_id !~ '^[0-9]+$' or (p_transfer_code is not null and p_transfer_code !~ '^TRF_[A-Za-z0-9]+$') or p_status not in ('succeeded','failed','reversed','pending') or p_amount_minor<=0 or p_currency<>'NGN' then raise exception 'Invalid Paystack Test transfer provider event' using errcode='22023'; end if;
  if p_provenance='provider_api' and (p_actor_user_id is null or not exists(select 1 from public.account_capabilities c where c.user_id=p_actor_user_id and c.capability='admin' and c.status='active')) then raise exception 'Active administrator required' using errcode='42501'; end if;
  insert into public.learning_instructor_payout_provider_events(provenance,provider_event_id,payload_digest,payout_item_reference,provider_transfer_id,provider_transfer_code,provider_status,amount_minor,currency)
  values(p_provenance,p_provider_event_id,p_payload_digest,p_reference,p_transfer_id,p_transfer_code,p_status,p_amount_minor,p_currency)
  on conflict (provider_event_id) do nothing returning id into event_id;
  if event_id is null then
    select * into existing from public.learning_instructor_payout_provider_events where provider_event_id=p_provider_event_id for update;
    if existing.payload_digest<>p_payload_digest or existing.payout_item_reference<>p_reference or existing.provider_transfer_id<>p_transfer_id or existing.provider_transfer_code is distinct from p_transfer_code or existing.provider_status<>p_status or existing.amount_minor<>p_amount_minor or existing.currency<>p_currency or existing.provenance<>p_provenance then
      select id into item_id from public.learning_instructor_payout_items where payout_item_reference=existing.payout_item_reference;
      perform public.open_learning_instructor_payout_finding('payout-event-duplicate-conflict:'||existing.id,item_id,existing.id,'provider_outcome_conflict','A duplicate provider event ID contained conflicting normalized transfer data');
      return query select 'duplicate_conflict',existing.id; return;
    end if;
    return query select 'already_received',existing.id; return;
  end if;
  return query select 'received',event_id;
end;$function$;

create or replace function public.process_learning_instructor_payout_provider_event(p_provider_event_id bigint)
returns table(outcome text,payout_item_id bigint) language plpgsql security definer set search_path to '' as $function$
declare ev public.learning_instructor_payout_provider_events%rowtype; item public.learning_instructor_payout_items%rowtype; r public.learning_instructor_earning_reservations%rowtype; e public.learning_instructor_earnings%rowtype; a public.learning_commercial_allocations%rowtype; o public.learning_orders%rowtype; ledger_key bigint; active_protection boolean; item_status_before text;
begin
  select * into ev from public.learning_instructor_payout_provider_events where id=p_provider_event_id for update;
  if not found then raise exception 'Payout provider event not found' using errcode='P0002'; end if;
  if exists(select 1 from public.learning_instructor_payout_event_processing_attempts p where p.provider_event_id=ev.id and (p.outcome in ('settled','released','reversed','already_processed') or (p.outcome='recorded' and ev.provider_status<>'failed'))) then
    return query select 'already_processed',p.payout_item_id from public.learning_instructor_payout_event_processing_attempts p where p.provider_event_id=ev.id and p.outcome in ('settled','released','reversed','recorded','already_processed') order by p.id desc limit 1; return;
  end if;
  select * into item from public.learning_instructor_payout_items where payout_item_reference=ev.payout_item_reference for update;
  if not found then
    perform public.open_learning_instructor_payout_finding('payout-event-unmatched:'||ev.id,null,ev.id,'unmatched_provider_event','Signed Test transfer event does not match a payout item');
    insert into public.learning_instructor_payout_event_processing_attempts(provider_event_id,outcome,detail) values(ev.id,'deferred','Payout item is not available yet');
    return query select 'deferred',null::bigint; return;
  end if;
  if item.provider_domain<>'test' or item.amount_minor<>ev.amount_minor or item.currency<>ev.currency then
    perform public.open_learning_instructor_payout_finding('payout-event-amount:'||ev.id,item.id,ev.id,'provider_amount_currency_mismatch','Signed provider event amount, currency, or domain mismatches payout item');
    insert into public.learning_instructor_payout_event_processing_attempts(provider_event_id,payout_item_id,outcome,detail) values(ev.id,item.id,'conflict','Provider amount, currency, or domain mismatch');
    return query select 'conflict',item.id; return;
  end if;
  if item.provider_transfer_id is not null and item.provider_transfer_id<>ev.provider_transfer_id then
    perform public.open_learning_instructor_payout_finding('payout-event-identity:'||ev.id,item.id,ev.id,'provider_identity_mismatch','Signed provider event transfer identity mismatches payout item');
    insert into public.learning_instructor_payout_event_processing_attempts(provider_event_id,payout_item_id,outcome,detail) values(ev.id,item.id,'conflict','Provider transfer identity mismatch');
    return query select 'conflict',item.id; return;
  end if;
  select * into r from public.learning_instructor_earning_reservations where id=item.reservation_id for update;
  select * into e from public.learning_instructor_earnings where id=item.earning_id for update;
  select * into a from public.learning_commercial_allocations where id=item.allocation_id for update;
  select * into o from public.learning_orders where id=a.order_id for update;
  if r.earning_id<>e.id or r.allocation_id<>a.id or e.instructor_id<>item.instructor_id or e.gross_amount_minor<>item.amount_minor then raise exception 'Payout item financial identity is invalid' using errcode='23514'; end if;
  lock table public.learning_payment_cases in share row exclusive mode;
  active_protection:=exists(select 1 from public.learning_payment_cases c where c.order_id=o.id and c.status in ('requested','submitting','pending','processing','needs_attention','opened','action_required','submitted','under_review'));
  item_status_before:=item.status;
  if ev.provider_status='pending' then
    if item.status in ('submitting','recovery_required') then
      update public.learning_instructor_payout_items set status='pending',provider_transfer_id=coalesce(provider_transfer_id,ev.provider_transfer_id),provider_transfer_code=coalesce(provider_transfer_code,ev.provider_transfer_code),provider_status=ev.provider_status,provider_received_at=now(),failure_code=null where id=item.id;
    elsif item.status not in ('pending','financially_blocked') then
      perform public.open_learning_instructor_payout_finding('payout-event-conflict:'||ev.id,item.id,ev.id,'provider_outcome_conflict','A delayed pending provider event conflicts with the existing terminal payout state');
      insert into public.learning_instructor_payout_event_processing_attempts(provider_event_id,payout_item_id,outcome,detail) values(ev.id,item.id,'conflict','Delayed pending provider outcome conflicts with local state');
      return query select 'conflict',item.id; return;
    end if;
    if item.status='financially_blocked' then update public.learning_instructor_payout_items set provider_transfer_id=coalesce(provider_transfer_id,ev.provider_transfer_id),provider_transfer_code=coalesce(provider_transfer_code,ev.provider_transfer_code),provider_status=ev.provider_status,provider_received_at=now() where id=item.id; end if;
    insert into public.learning_instructor_payout_item_events(payout_item_id,event_type,from_status,to_status,provenance,provider_event_id,payload_digest,metadata) values(item.id,'paystack.pending',item_status_before,case when item_status_before='financially_blocked' then 'financially_blocked' else 'pending' end,case when ev.provenance='provider_webhook' then 'webhook' else 'provider_api' end,ev.provider_event_id,ev.payload_digest,jsonb_build_object('provider_transfer_id',ev.provider_transfer_id,'provider_status',ev.provider_status));
    insert into public.learning_instructor_payout_event_processing_attempts(provider_event_id,payout_item_id,outcome,detail) values(ev.id,item.id,'recorded','Provider transfer remains pending');
    return query select 'recorded',item.id; return;
  elsif ev.provider_status='succeeded' then
    select ledger_transaction_id into ledger_key from public.learning_instructor_payout_settlements where payout_item_id=item.id for update;
    if ledger_key is not null then
      insert into public.learning_instructor_payout_event_processing_attempts(provider_event_id,payout_item_id,outcome,detail) values(ev.id,item.id,'already_processed','Payout settlement already exists');
      return query select 'already_processed',item.id; return;
    end if;
    if item.status in ('approved','failed','reversed','cancelled') then
      perform public.open_learning_instructor_payout_finding('payout-event-conflict:'||ev.id,item.id,ev.id,'provider_outcome_conflict','A later success conflicts with the existing terminal payout state');
      insert into public.learning_instructor_payout_event_processing_attempts(provider_event_id,payout_item_id,outcome,detail) values(ev.id,item.id,'conflict','Conflicting terminal provider outcome');
      return query select 'conflict',item.id; return;
    end if;
    if active_protection or e.status<>'reserved' or a.status<>'allocated' or o.status<>'paid' or item.status='financially_blocked' then
      if item.status in ('submitting','pending','recovery_required') then update public.learning_instructor_payout_items set status='financially_blocked',provider_transfer_id=coalesce(provider_transfer_id,ev.provider_transfer_id),provider_transfer_code=coalesce(provider_transfer_code,ev.provider_transfer_code),provider_status=ev.provider_status,provider_received_at=now(),failure_code='financial_protection' where id=item.id; end if;
      perform public.open_learning_instructor_payout_finding('payout-success-blocked:'||item.id,item.id,ev.id,'provider_outcome_financially_blocked','Provider success cannot settle because the earning is financially ineligible');
      insert into public.learning_instructor_payout_item_events(payout_item_id,event_type,from_status,to_status,provenance,provider_event_id,payload_digest,metadata) values(item.id,'paystack.succeeded',item_status_before,'financially_blocked',case when ev.provenance='provider_webhook' then 'webhook' else 'provider_api' end,ev.provider_event_id,ev.payload_digest,jsonb_build_object('provider_transfer_id',ev.provider_transfer_id,'provider_status',ev.provider_status));
      insert into public.learning_instructor_payout_event_processing_attempts(provider_event_id,payout_item_id,outcome,detail) values(ev.id,item.id,'deferred','Provider success retained; settlement is financially blocked');
      return query select 'deferred',item.id; return;
    end if;
    if item.status in ('submitting','pending','recovery_required') then update public.learning_instructor_payout_items set status='succeeded',provider_transfer_id=coalesce(provider_transfer_id,ev.provider_transfer_id),provider_transfer_code=coalesce(provider_transfer_code,ev.provider_transfer_code),provider_status=ev.provider_status,provider_received_at=now(),failure_code=null where id=item.id; end if;
    if ledger_key is null then
      insert into public.learning_ledger_transactions(order_id,transaction_type,currency,description) values(o.id,'instructor_payout_settlement',item.currency,'Authoritative Paystack Test instructor payout settlement') returning id into ledger_key;
      insert into public.learning_ledger_entries(transaction_id,line_number,account_code,amount_minor,currency,counterparty_type,counterparty_reference) values
        -- E2 reservation is an operational lock and intentionally adds no
        -- ledger movement, so the released earning remains carried in the
        -- available-liability account until this authoritative settlement.
        (ledger_key,1,'liability.instructor_earnings_available',item.amount_minor,item.currency,'instructor_earning',e.id::text),
        (ledger_key,2,'asset.paystack_transfer_clearing',-item.amount_minor,item.currency,'learning_instructor_payout_item',item.payout_item_reference);
      update public.learning_instructor_earnings set status='paid',paid_at=now(),hold_reason='Paid through an authoritative Paystack Test transfer' where id=e.id and status='reserved';
      if not found then raise exception 'Reserved earning cannot be settled' using errcode='40001'; end if;
      insert into public.learning_instructor_payout_settlements(payout_item_id,earning_id,reservation_id,ledger_transaction_id,provider_event_id,amount_minor,currency) values(item.id,e.id,r.id,ledger_key,ev.id,item.amount_minor,item.currency);
      insert into public.learning_instructor_earning_events(earning_id,event_type,from_status,to_status,ledger_transaction_id,metadata) values(e.id,'earning.paid','reserved','paid',ledger_key,jsonb_build_object('payout_item_reference',item.payout_item_reference,'provider_event_id',ev.provider_event_id,'provenance',ev.provenance));
      insert into public.learning_instructor_payout_item_events(payout_item_id,event_type,from_status,to_status,provenance,provider_event_id,payload_digest,metadata) values(item.id,'paystack.succeeded',item_status_before,'succeeded',case when ev.provenance='provider_webhook' then 'webhook' else 'provider_api' end,ev.provider_event_id,ev.payload_digest,jsonb_build_object('provider_transfer_id',ev.provider_transfer_id,'settlement_ledger_transaction_id',ledger_key));
      insert into public.learning_instructor_payout_event_processing_attempts(provider_event_id,payout_item_id,outcome,detail) values(ev.id,item.id,'settled','Payout settled exactly once');
      perform public.resolve_learning_instructor_payout_findings(item.id,'Resolved by authoritative payout settlement');
      return query select 'settled',item.id; return;
    end if;
    insert into public.learning_instructor_payout_event_processing_attempts(provider_event_id,payout_item_id,outcome,detail) values(ev.id,item.id,'already_processed','Payout settlement already exists');
    return query select 'already_processed',item.id; return;
  elsif ev.provider_status='failed' then
    if item.status in ('approved','succeeded','reversed','cancelled','financially_blocked') then
      perform public.open_learning_instructor_payout_finding('payout-event-conflict:'||ev.id,item.id,ev.id,'provider_outcome_conflict','A failed provider event conflicts with the existing terminal payout state');
      insert into public.learning_instructor_payout_event_processing_attempts(provider_event_id,payout_item_id,outcome,detail) values(ev.id,item.id,'conflict','Conflicting terminal provider outcome');
      return query select 'conflict',item.id; return;
    end if;
    if item.status<>'failed' then update public.learning_instructor_payout_items set status='failed',provider_transfer_id=coalesce(provider_transfer_id,ev.provider_transfer_id),provider_transfer_code=coalesce(provider_transfer_code,ev.provider_transfer_code),provider_status=ev.provider_status,provider_received_at=now(),failure_code='provider_failed' where id=item.id; end if;
    if not active_protection and e.status='reserved' and a.status='allocated' and o.status='paid' then
      update public.learning_instructor_earnings set status='available',reserved_at=null,hold_reason=null where id=e.id;
      insert into public.learning_instructor_earning_events(earning_id,event_type,from_status,to_status,metadata) values(e.id,'earning.payout_reservation_released','reserved','available',jsonb_build_object('payout_item_reference',item.payout_item_reference,'provider_event_id',ev.provider_event_id));
      insert into public.learning_instructor_payout_item_events(payout_item_id,event_type,from_status,to_status,provenance,provider_event_id,payload_digest,metadata) values(item.id,'paystack.failed',item_status_before,'failed',case when ev.provenance='provider_webhook' then 'webhook' else 'provider_api' end,ev.provider_event_id,ev.payload_digest,jsonb_build_object('provider_transfer_id',ev.provider_transfer_id,'reservation_released',true)) on conflict (provider_event_id) do nothing;
      insert into public.learning_instructor_payout_event_processing_attempts(provider_event_id,payout_item_id,outcome,detail) values(ev.id,item.id,'released','Authoritative failed payout released reservation') on conflict do nothing;
      perform public.resolve_learning_instructor_payout_findings(item.id,'Resolved by authoritative failed-payout release');
      return query select 'released',item.id; return;
    end if;
    perform public.open_learning_instructor_payout_finding('payout-failed-blocked:'||item.id,item.id,ev.id,'provider_outcome_financially_blocked','Failed payout reservation remains protected pending controlled resolution');
    insert into public.learning_instructor_payout_item_events(payout_item_id,event_type,from_status,to_status,provenance,provider_event_id,payload_digest,metadata) values(item.id,'paystack.failed',item_status_before,'failed',case when ev.provenance='provider_webhook' then 'webhook' else 'provider_api' end,ev.provider_event_id,ev.payload_digest,jsonb_build_object('provider_transfer_id',ev.provider_transfer_id,'reservation_released',false)) on conflict (provider_event_id) do nothing;
    insert into public.learning_instructor_payout_event_processing_attempts(provider_event_id,payout_item_id,outcome,detail) values(ev.id,item.id,'recorded','Authoritative failed payout retained protected reservation') on conflict do nothing;
    return query select 'recorded',item.id; return;
  else
    if item.status='succeeded' then
      update public.learning_instructor_payout_items set status='reversed',provider_transfer_id=coalesce(provider_transfer_id,ev.provider_transfer_id),provider_transfer_code=coalesce(provider_transfer_code,ev.provider_transfer_code),provider_status=ev.provider_status,provider_received_at=now() where id=item.id;
      perform public.open_learning_instructor_payout_finding('settled-payout-reversed:'||item.id,item.id,ev.id,'settled_payout_reversed_requires_controlled_resolution','A settled payout was reversed by Paystack and requires controlled commercial resolution');
    elsif item.status in ('submitting','pending','recovery_required') then
      update public.learning_instructor_payout_items set status='reversed',provider_transfer_id=coalesce(provider_transfer_id,ev.provider_transfer_id),provider_transfer_code=coalesce(provider_transfer_code,ev.provider_transfer_code),provider_status=ev.provider_status,provider_received_at=now(),failure_code=null where id=item.id;
      perform public.open_learning_instructor_payout_finding('payout-reversed:'||item.id,item.id,ev.id,'terminal_payout_inconsistent_state','Reversed payout retains its reservation until controlled reconciliation');
    elsif item.status<>'reversed' then
      perform public.open_learning_instructor_payout_finding('payout-event-conflict:'||ev.id,item.id,ev.id,'provider_outcome_conflict','A reversed provider event conflicts with the existing terminal payout state');
      insert into public.learning_instructor_payout_event_processing_attempts(provider_event_id,payout_item_id,outcome,detail) values(ev.id,item.id,'conflict','Conflicting terminal provider outcome');
      return query select 'conflict',item.id; return;
    end if;
    insert into public.learning_instructor_payout_item_events(payout_item_id,event_type,from_status,to_status,provenance,provider_event_id,payload_digest,metadata) values(item.id,'paystack.reversed',item_status_before,'reversed',case when ev.provenance='provider_webhook' then 'webhook' else 'provider_api' end,ev.provider_event_id,ev.payload_digest,jsonb_build_object('provider_transfer_id',ev.provider_transfer_id));
    insert into public.learning_instructor_payout_event_processing_attempts(provider_event_id,payout_item_id,outcome,detail) values(ev.id,item.id,'reversed','Authoritative reversed payout retained for reconciliation');
    return query select 'reversed',item.id; return;
  end if;
end;$function$;

drop function if exists public.list_learning_instructor_payout_reconciliation_findings(uuid,integer);
create function public.list_learning_instructor_payout_reconciliation_findings(p_operator_id uuid,p_limit integer default 100)
returns table(finding_id bigint,payout_item_reference text,finding_type text,status text,detail text,created_at timestamptz) language plpgsql stable security definer set search_path to '' as $function$
begin
  if p_operator_id is null or not exists(select 1 from public.account_capabilities c where c.user_id=p_operator_id and c.capability='admin' and c.status='active') then raise exception 'Active administrator required' using errcode='42501'; end if;
  return query select f.id,i.payout_item_reference,f.finding_type,f.status,f.detail,f.created_at from public.learning_instructor_payout_reconciliation_findings f left join public.learning_instructor_payout_items i on i.id=f.payout_item_id order by f.created_at desc,f.id desc limit least(greatest(coalesce(p_limit,100),1),200);
end;$function$;

revoke all on function public.prevent_learning_instructor_payout_e4_history_mutation(),public.prevent_learning_instructor_payout_finding_mutation(),public.open_learning_instructor_payout_finding(text,bigint,bigint,text,text),public.receive_paystack_test_transfer_provider_event(text,text,text,text,text,text,text,bigint,text,uuid),public.process_learning_instructor_payout_provider_event(bigint),public.list_learning_instructor_payout_reconciliation_findings(uuid,integer) from public,anon,authenticated;
grant execute on function public.prevent_learning_instructor_payout_e4_history_mutation(),public.prevent_learning_instructor_payout_finding_mutation(),public.open_learning_instructor_payout_finding(text,bigint,bigint,text,text),public.receive_paystack_test_transfer_provider_event(text,text,text,text,text,text,text,bigint,text,uuid),public.process_learning_instructor_payout_provider_event(bigint),public.list_learning_instructor_payout_reconciliation_findings(uuid,integer) to postgres,service_role;

commit;

-- Corrective pass: E3 compatibility calls delegate to the E4 receipt and
-- finalizer; reconciliation resolution is itself immutable history.
begin;

drop index if exists public.learning_instructor_payout_reconciliation_findings_open_idx;
alter table public.learning_instructor_payout_reconciliation_findings drop column status, drop column resolved_at;
create table public.learning_instructor_payout_reconciliation_finding_events (
  id bigint generated by default as identity primary key,
  finding_id bigint not null references public.learning_instructor_payout_reconciliation_findings(id) on delete restrict,
  event_type text not null check (event_type in ('opened','resolved')),
  detail text not null check (length(detail)<=500),
  occurred_at timestamptz not null default now(),
  unique(finding_id,event_type)
);
alter table public.learning_instructor_payout_reconciliation_finding_events enable row level security;
revoke all on public.learning_instructor_payout_reconciliation_finding_events from public,anon,authenticated;
grant select,insert,update,delete on public.learning_instructor_payout_reconciliation_finding_events to postgres,service_role;
create trigger prevent_learning_instructor_payout_finding_event_mutation before update or delete on public.learning_instructor_payout_reconciliation_finding_events for each row execute function public.prevent_learning_instructor_payout_e4_history_mutation();

create or replace function public.prevent_learning_instructor_payout_finding_mutation()
returns trigger language plpgsql security definer set search_path to '' as $function$
begin raise exception 'Payout reconciliation findings are immutable' using errcode='42501'; end;$function$;

create or replace function public.open_learning_instructor_payout_finding(p_finding_key text,p_payout_item_id bigint,p_provider_event_id bigint,p_finding_type text,p_detail text)
returns void language plpgsql security definer set search_path to '' as $function$
declare finding_id bigint;
begin
  insert into public.learning_instructor_payout_reconciliation_findings(finding_key,payout_item_id,provider_event_id,finding_type,detail)
  values(p_finding_key,p_payout_item_id,p_provider_event_id,p_finding_type,left(p_detail,500))
  on conflict (finding_key) do nothing;
  select id into finding_id from public.learning_instructor_payout_reconciliation_findings where finding_key=p_finding_key;
  insert into public.learning_instructor_payout_reconciliation_finding_events(finding_id,event_type,detail) values(finding_id,'opened',left(p_detail,500)) on conflict (finding_id,event_type) do nothing;
end;$function$;

create or replace function public.resolve_learning_instructor_payout_findings(p_payout_item_id bigint,p_detail text)
returns void language plpgsql security definer set search_path to '' as $function$
begin
  insert into public.learning_instructor_payout_reconciliation_finding_events(finding_id,event_type,detail)
  select f.id,'resolved',left(p_detail,500) from public.learning_instructor_payout_reconciliation_findings f
  where f.payout_item_id=p_payout_item_id and not exists(select 1 from public.learning_instructor_payout_reconciliation_finding_events e where e.finding_id=f.id and e.event_type='resolved')
  on conflict (finding_id,event_type) do nothing;
end;$function$;

create or replace function public.reprocess_learning_instructor_payout_provider_event(p_provider_event_id bigint,p_actor_user_id uuid)
returns table(outcome text,payout_item_id bigint) language plpgsql security definer set search_path to '' as $function$
begin
  if p_actor_user_id is null or not exists(select 1 from public.account_capabilities c where c.user_id=p_actor_user_id and c.capability='admin' and c.status='active') then raise exception 'Active administrator required' using errcode='42501'; end if;
  if not exists(select 1 from public.learning_instructor_payout_provider_events e where e.id=p_provider_event_id) then raise exception 'Payout provider event not found' using errcode='P0002'; end if;
  return query select * from public.process_learning_instructor_payout_provider_event(p_provider_event_id);
end;$function$;

create or replace function public.receive_paystack_test_transfer_event(p_provider_event_id text,p_payload_digest text,p_reference text,p_transfer_id text,p_transfer_code text,p_status text,p_amount_minor bigint,p_currency text,p_payload jsonb)
returns table(outcome text,payout_item_id bigint) language plpgsql security definer set search_path to '' as $function$
declare receipt_id bigint;
begin
  select provider_event_id into receipt_id from public.receive_paystack_test_transfer_provider_event('provider_webhook',p_provider_event_id,p_payload_digest,p_reference,p_transfer_id,p_transfer_code,p_status,p_amount_minor,p_currency,null) limit 1;
  return query select * from public.process_learning_instructor_payout_provider_event(receipt_id);
end;$function$;

create or replace function public.record_learning_instructor_test_transfer_verification(p_payout_item_id bigint,p_transfer_id text,p_transfer_code text,p_provider_status text,p_actor_user_id uuid)
returns void language plpgsql security definer set search_path to '' as $function$
declare item public.learning_instructor_payout_items%rowtype; receipt_id bigint; provider_event_identity text; payload jsonb;
begin
  if p_actor_user_id is null or not exists(select 1 from public.account_capabilities c where c.user_id=p_actor_user_id and c.capability='admin' and c.status='active') then raise exception 'Active administrator required' using errcode='42501'; end if;
  select * into item from public.learning_instructor_payout_items where id=p_payout_item_id for update;
  if not found or item.provider_domain<>'test' then raise exception 'Test payout item required' using errcode='22023'; end if;
  provider_event_identity:='provider-api:'||item.payout_item_reference||':'||p_provider_status||':'||p_transfer_id;
  payload:=jsonb_build_object('reference',item.payout_item_reference,'transfer_id',p_transfer_id,'transfer_code',p_transfer_code,'status',p_provider_status,'amount_minor',item.amount_minor,'currency',item.currency,'domain','test');
  select provider_event_id into receipt_id from public.receive_paystack_test_transfer_provider_event('provider_api',provider_event_identity,encode(extensions.digest(convert_to(payload::text,'UTF8'),'sha256'),'hex'),item.payout_item_reference,p_transfer_id,p_transfer_code,p_provider_status,item.amount_minor,item.currency,p_actor_user_id) limit 1;
  perform public.process_learning_instructor_payout_provider_event(receipt_id);
end;$function$;

-- The transaction-1 listing RPC has a smaller table-return shape. PostgreSQL
-- cannot replace that return type in place, so this is the one required
-- compatibility drop before creating the final read model.
drop function if exists public.list_learning_instructor_payout_reconciliation_findings(uuid,integer);
create or replace function public.list_learning_instructor_payout_reconciliation_findings(p_operator_id uuid,p_limit integer default 100)
returns table(finding_id bigint,provider_event_id bigint,payout_item_reference text,finding_type text,status text,detail text,created_at timestamptz) language plpgsql stable security definer set search_path to '' as $function$
begin
  if p_operator_id is null or not exists(select 1 from public.account_capabilities c where c.user_id=p_operator_id and c.capability='admin' and c.status='active') then raise exception 'Active administrator required' using errcode='42501'; end if;
  return query select f.id,f.provider_event_id,i.payout_item_reference,f.finding_type,case when exists(select 1 from public.learning_instructor_payout_reconciliation_finding_events e where e.finding_id=f.id and e.event_type='resolved') then 'resolved' else 'open' end,f.detail,f.created_at from public.learning_instructor_payout_reconciliation_findings f left join public.learning_instructor_payout_items i on i.id=f.payout_item_id order by f.created_at desc,f.id desc limit least(greatest(coalesce(p_limit,100),1),200);
end;$function$;

revoke all on function public.resolve_learning_instructor_payout_findings(bigint,text),public.reprocess_learning_instructor_payout_provider_event(bigint,uuid) from public,anon,authenticated;
grant execute on function public.resolve_learning_instructor_payout_findings(bigint,text),public.reprocess_learning_instructor_payout_provider_event(bigint,uuid) to postgres,service_role;
commit;
